'use client';
import {useEffect,useState,useRef} from 'react';
import {createClient} from '@supabase/supabase-js';
import {fileApi,uploadProduction,discardProduction} from '../lib/r2-client';
import {LayoutDashboard,Zap,Users,PanelsTopLeft,CircleCheckBig,CalendarDays,DollarSign,UserRoundCog,Settings,Bell,Search,ArrowUpRight,Menu,X,LogOut,FolderOpen,PackageCheck,FileText,WalletCards,Clapperboard,ChevronLeft,Plus,Save,Trash2,Pencil,Clock3,Upload,Play,Send,MessageSquare,Check,RefreshCw,Paperclip} from 'lucide-react';

const supabase=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL,process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY||process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY);
const agencyNav=[['Visão geral',LayoutDashboard],['Comando',Zap],['Clientes',Users],['Produção',PanelsTopLeft],['Aprovações',CircleCheckBig],['Calendário',CalendarDays],['Financeiro',DollarSign],['Equipe',UserRoundCog]];
const clientNav=[['Início',LayoutDashboard],['Aprovações',CircleCheckBig],['Calendário',CalendarDays],['Entregas',PackageCheck],['Arquivos',FolderOpen]];

export default function Page(){
 const [session,setSession]=useState(undefined),[ctx,setCtx]=useState(null),[error,setError]=useState('');
 useEffect(()=>{supabase.auth.getSession().then(({data})=>setSession(data.session));const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(!session){setCtx(null);return} loadContext(session.user.id).then(setCtx).catch(e=>setError(e.message))},[session]);
 if(session===undefined)return <Splash/>; if(!session)return <Login onError={setError} error={error}/>; if(!ctx)return <Splash text={error||'Preparando seu ambiente...'}/>;
 return ctx.role==='client_user'?<ClientPortal ctx={ctx}/>:<AgencyApp ctx={ctx}/>;
}
async function loadContext(userId){
 const {data:profile}=await supabase.from('profiles').select('full_name').eq('id',userId).single();
 const {data:memberships,error:mErr}=await supabase.from('organization_members').select('role, organization_id, organizations(id,name,slug)').eq('user_id',userId).eq('is_active',true).limit(1);if(mErr)throw mErr;
 const m=memberships?.[0];if(!m)throw new Error('Seu usuário ainda não está vinculado a uma organização.');
 let client=null;if(m.role==='client_user'){const {data,error}=await supabase.from('client_users').select('clients(id,name,slug,status)').eq('user_id',userId).limit(1);if(error)throw error;client=data?.[0]?.clients||null;}
 return {name:profile?.full_name||'Usuário',role:m.role,organization:m.organizations,client};
}
function Login({error,onError}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);onError('');const {error}=await supabase.auth.signInWithPassword({email,password});if(error)onError(error.message==='Invalid login credentials'?'E-mail ou senha incorretos.':error.message);setBusy(false)}return <main className="loginPage"><section className="loginBrand"><div className="brand big">AVESSO<span>.</span></div><h1>A operação por trás<br/>da criação.</h1><p>Clientes, produção, aprovação e operação no mesmo lugar.</p></section><section className="loginBox"><div className="loginCard"><small>ACESSO AVESSO</small><h2>Entre no seu espaço.</h2><p>O ambiente é definido automaticamente pelo seu perfil.</p><form onSubmit={submit}><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="loginError">{error}</div>}<button className="loginBtn" disabled={busy}>{busy?'Entrando...':'Entrar no AVESSO →'}</button></form></div></section></main>}

function AgencyApp({ctx}){const [active,setActive]=useState('Visão geral'),[mobile,setMobile]=useState(false),[selectedClient,setSelectedClient]=useState(null),[clientTab,setClientTab]=useState('Visão geral');
 function nav(name){setSelectedClient(null);setActive(name)}
 return <main className="shell"><Sidebar nav={agencyNav} active={selectedClient?'Clientes':active} setActive={nav} mobile={mobile} setMobile={setMobile} org={ctx.organization?.name}/><section className="content"><Top ctx={ctx} mobile={mobile} setMobile={setMobile} eyebrow={selectedClient?'CLIENTE 360°':active.toUpperCase()} subtitle={selectedClient?`Tudo de ${selectedClient.name} em um só lugar.`:'A operação por trás da criação.'}/>{selectedClient?<Client360 client={selectedClient} ctx={ctx} tab={clientTab} setTab={setClientTab} onBack={()=>setSelectedClient(null)} onClientUpdated={setSelectedClient}/>:<AgencyModule active={active} ctx={ctx} onClient={c=>{setSelectedClient(c);setClientTab('Visão geral')}}/>}</section></main>}
function AgencyModule({active,ctx,onClient}){if(active==='Clientes')return <ClientsPage ctx={ctx} onClient={onClient}/>;if(active==='Visão geral')return <Overview ctx={ctx}/>;if(active==='Calendário')return <RecordingAgenda ctx={ctx} full/>;if(active==='Financeiro')return <Finance ctx={ctx}/>;return <EmptyModule name={active}/>}
function Overview({ctx}){const [m,setM]=useState({clients:'—',production:'—',approvals:'—'});useEffect(()=>{(async()=>{const org=ctx.organization.id;const [c,p,a]=await Promise.all([supabase.from('clients').select('id',{count:'exact',head:true}).eq('organization_id',org).eq('status','active'),supabase.from('demands').select('id',{count:'exact',head:true}).eq('organization_id',org).in('status',['briefing','awaiting_material','in_production','internal_review','adjustments','approved']),supabase.from('demands').select('id',{count:'exact',head:true}).eq('organization_id',org).eq('status','with_client')]);setM({clients:c.count??0,production:p.count??0,approvals:a.count??0})})()},[ctx.organization.id]);return <><div className="metrics"><article className="metric"><small>CLIENTES ATIVOS</small><strong>{m.clients}</strong><span>carteira da agência</span></article><article className="metric"><small>EM PRODUÇÃO</small><strong>{m.production}</strong><span>demandas abertas</span></article><article className="metric"><small>APROVAÇÕES</small><strong>{m.approvals}</strong><span>aguardando cliente</span></article></div><RecordingAgenda ctx={ctx}/></>}

function RecordingAgenda({ctx,full=false}){
 const [sessions,setSessions]=useState([]),[clients,setClients]=useState([]),[show,setShow]=useState(false),[edit,setEdit]=useState(null),[month,setMonth]=useState(()=>new Date());
 async function load(){const start=new Date(month.getFullYear(),month.getMonth(),1),end=new Date(month.getFullYear(),month.getMonth()+1,1);const [{data:s},{data:c}]=await Promise.all([supabase.from('recording_sessions').select('*,clients(name)').eq('organization_id',ctx.organization.id).gte('starts_at',start.toISOString()).lt('starts_at',end.toISOString()).order('starts_at'),supabase.from('clients').select('id,name').eq('organization_id',ctx.organization.id).eq('status','active').order('name')]);setSessions(s||[]);setClients(c||[])}
 useEffect(()=>{load()},[ctx.organization.id,month]);
 const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),cells=[...Array(first).fill(null),...Array.from({length:days},(_,i)=>i+1)];
 function daySessions(d){return sessions.filter(x=>new Date(x.starts_at).getDate()===d)}
 return <section className={'recordingAgenda '+(full?'agendaFull':'')}><div className="agendaHead"><div><small>AGENDA GERAL DA AGÊNCIA</small><h2>Agenda de gravações</h2><p>Clientes e horários no mesmo calendário para evitar conflitos.</p></div><button className="primary" onClick={()=>{setEdit(null);setShow(true)}}><Plus size={16}/> Nova gravação</button></div><div className="monthNav"><button onClick={()=>setMonth(new Date(y,m-1,1))}>‹</button><strong>{month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button onClick={()=>setMonth(new Date(y,m+1,1))}>›</button></div><div className="calendarGrid">{['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=><div className="weekday" key={x}>{x}</div>)}{cells.map((d,i)=><div className={'calDay '+(!d?'blank':'')} key={i}>{d&&<><b>{d}</b>{daySessions(d).map(s=><button className="shoot" key={s.id} onClick={()=>{setEdit(s);setShow(true)}}><span>{new Date(s.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span>{s.clients?.name}</button>)}<button className="dayAdd" onClick={()=>{setEdit({presetDate:`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`});setShow(true)}}>+</button></>}</div>)}</div>{show&&<RecordingModal ctx={ctx} clients={clients} session={edit} onClose={()=>{setShow(false);setEdit(null)}} onSaved={()=>{setShow(false);setEdit(null);load()}}/>}</section>
}
function RecordingModal({ctx,clients,session,onClose,onSaved}){
 const start=session?.starts_at?new Date(session.starts_at):null,end=session?.ends_at?new Date(session.ends_at):null;
 const [f,setF]=useState({client_id:session?.client_id||'',date:session?.presetDate||start?.toISOString().slice(0,10)||'',start:start?start.toTimeString().slice(0,5):'',end:end?end.toTimeString().slice(0,5):'',location:session?.location||'',responsible_name:session?.responsible_name||'',notes:session?.notes||'',status:session?.status||'scheduled'}),[err,setErr]=useState(''),[saving,setSaving]=useState(false);
 function u(k,v){setF(x=>({...x,[k]:v}))} async function save(e){e.preventDefault();setErr('');setSaving(true);const a=new Date(`${f.date}T${f.start}:00`),b=new Date(`${f.date}T${f.end}:00`);if(b<=a){setErr('O horário final precisa ser depois do inicial.');setSaving(false);return}let q=supabase.from('recording_sessions').select('id,starts_at,ends_at,clients(name)').eq('organization_id',ctx.organization.id).neq('status','cancelled').lt('starts_at',b.toISOString()).gt('ends_at',a.toISOString());if(session?.id)q=q.neq('id',session.id);const {data:conf}=await q;if(conf?.length){const c=conf[0];setErr(`Conflito: ${c.clients?.name||'outro cliente'} já tem gravação das ${new Date(c.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} às ${new Date(c.ends_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}.`);setSaving(false);return}const payload={organization_id:ctx.organization.id,client_id:f.client_id,starts_at:a.toISOString(),ends_at:b.toISOString(),location:f.location||null,responsible_name:f.responsible_name||null,notes:f.notes||null,status:f.status};const r=session?.id?await supabase.from('recording_sessions').update(payload).eq('id',session.id):await supabase.from('recording_sessions').insert(payload);if(r.error)setErr(r.error.message);else onSaved();setSaving(false)}
 return <div className="modalBackdrop"><form className="modalCard" onSubmit={save}><div className="modalHead"><div><small>AGENDA DE GRAVAÇÃO</small><h2>{session?.id?'Editar gravação':'Nova gravação'}</h2></div><button type="button" className="modalClose" onClick={onClose}><X size={20}/></button></div><div className="formGrid"><label>Cliente *<select required value={f.client_id} onChange={e=>u('client_id',e.target.value)}><option value="">Selecione</option>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Data *<input required type="date" value={f.date} onChange={e=>u('date',e.target.value)}/></label><label>Início *<input required type="time" value={f.start} onChange={e=>u('start',e.target.value)}/></label><label>Fim *<input required type="time" value={f.end} onChange={e=>u('end',e.target.value)}/></label><label>Local<input value={f.location} onChange={e=>u('location',e.target.value)} placeholder="Estúdio, endereço..."/></label><label>Responsável / equipe<input value={f.responsible_name} onChange={e=>u('responsible_name',e.target.value)}/></label><label className="wide">Observações<textarea value={f.notes} onChange={e=>u('notes',e.target.value)}/></label></div>{err&&<div className="loginError">{err}</div>}<div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}><Save size={16}/>{saving?'Salvando...':'Salvar gravação'}</button></div></form></div>
}
function EmptyModule({name}){return <div className="emptyModule"><div className="emptyIcon">+</div><small>MÓDULO {name.toUpperCase()}</small><h2>{name}</h2><p>A navegação já está ativa. Os dados operacionais deste módulo serão conectados nas próximas etapas.</p></div>}
function ClientsPage({ctx,onClient}){
 const [clients,setClients]=useState([]),[loading,setLoading]=useState(true),[err,setErr]=useState(''),[showNew,setShowNew]=useState(false);
 async function load(){setLoading(true);const {data,error}=await supabase.from('clients').select('id,name,slug,status,organization_id,contact_name,contact_email,whatsapp,instagram,website,portal_access_status').eq('organization_id',ctx.organization.id).order('name');if(error)setErr(error.message);else setClients(data||[]);setLoading(false)}
 useEffect(()=>{load()},[ctx.organization.id]);
 return <section className="module"><div className="moduleHead"><div><small>CARTEIRA</small><h2>Clientes</h2><p>Cadastre, abra e administre cada cliente sem sair do AVESSO.</p></div><button className="primary" onClick={()=>setShowNew(true)}><Plus size={16}/> Novo cliente</button></div>{loading?<p>Carregando...</p>:err?<div className="loginError">{err}</div>:clients.length?<div className="clientCards">{clients.map(c=><button className="clientCard" key={c.id} onClick={()=>onClient(c)}><div className="clientInitial">{c.name[0]}</div><div><span className="statusDot"/> <small>{c.status==='active'?'ATIVO':c.status.toUpperCase()}</small><h3>{c.name}</h3><p>Abrir Cliente 360°</p></div><ArrowUpRight/></button>)}</div>:<div className="emptyModule compact"><small>CARTEIRA VAZIA</small><h2>Seu próximo cliente começa aqui.</h2><p>Clique em “Novo cliente” para criar o Cliente 360°.</p></div>}{showNew&&<NewClientModal ctx={ctx} onClose={()=>setShowNew(false)} onCreated={async c=>{setShowNew(false);await load();onClient(c)}}/>}</section>}
function slugify(v){return v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}
function NewClientModal({ctx,onClose,onCreated}){
 const [form,setForm]=useState({name:'',legal_name:'',status:'active',contact_name:'',contact_email:'',whatsapp:'',instagram:'',website:'',notes:'',portal:false,portal_email:''}),[saving,setSaving]=useState(false),[err,setErr]=useState('');
 function f(k,v){setForm(x=>({...x,[k]:v}))}
 async function submit(e){e.preventDefault();setSaving(true);setErr('');let base=slugify(form.name)||'cliente',slug=base,n=2;while(true){const {data}=await supabase.from('clients').select('id').eq('organization_id',ctx.organization.id).eq('slug',slug).maybeSingle();if(!data)break;slug=`${base}-${n++}`}
  const payload={organization_id:ctx.organization.id,name:form.name.trim(),legal_name:form.legal_name||null,slug,status:form.status,contact_name:form.contact_name||null,contact_email:form.contact_email||null,whatsapp:form.whatsapp||null,instagram:form.instagram||null,website:form.website||null,notes:form.notes||null,portal_email:form.portal?form.portal_email||form.contact_email||null:null,portal_access_status:form.portal?'pending':'not_requested'};
  const {data,error}=await supabase.from('clients').insert(payload).select('id,name,slug,status,organization_id').single();if(error){setErr(error.message);setSaving(false);return}
  const {error:ce}=await supabase.from('contracts').insert({client_id:data.id,organization_id:ctx.organization.id,status:'defining'});if(ce){setErr('Cliente criado, mas o contrato inicial não pôde ser criado: '+ce.message);setSaving(false);return}onCreated(data)
 }
 return <div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modalCard" onSubmit={submit}><div className="modalHead"><div><small>NOVO CLIENTE</small><h2>Criar Cliente 360°</h2><p>Os dados podem ser completados ou alterados depois.</p></div><button type="button" className="modalClose" onClick={onClose}><X size={20}/></button></div><div className="formGrid"><label>Nome do cliente *<input required autoFocus value={form.name} onChange={e=>f('name',e.target.value)} placeholder="Ex.: Cervejando com Diego"/></label><label>Empresa / razão social<input value={form.legal_name} onChange={e=>f('legal_name',e.target.value)} placeholder="Opcional"/></label><label>Status<select value={form.status} onChange={e=>f('status',e.target.value)}><option value="active">Ativo</option><option value="paused">Pausado</option></select></label><label>Contato principal<input value={form.contact_name} onChange={e=>f('contact_name',e.target.value)} placeholder="Nome da pessoa"/></label><label>E-mail<input type="email" value={form.contact_email} onChange={e=>f('contact_email',e.target.value)} placeholder="cliente@email.com"/></label><label>WhatsApp<input value={form.whatsapp} onChange={e=>f('whatsapp',e.target.value)} placeholder="(16) 99999-9999"/></label><label>Instagram<input value={form.instagram} onChange={e=>f('instagram',e.target.value)} placeholder="@cliente"/></label><label>Site<input value={form.website} onChange={e=>f('website',e.target.value)} placeholder="https://..."/></label><label className="wide">Observações<textarea value={form.notes} onChange={e=>f('notes',e.target.value)} placeholder="Informações importantes sobre o cliente..."/></label></div><div className="portalChoice"><label className="checkLine"><input type="checkbox" checked={form.portal} onChange={e=>f('portal',e.target.checked)}/><span><b>Preparar acesso ao Portal do Cliente</b><small>O cliente será marcado como acesso pendente. A ativação do login será feita na etapa de convite seguro.</small></span></label>{form.portal&&<label>E-mail para acesso<input type="email" value={form.portal_email} onChange={e=>f('portal_email',e.target.value)} placeholder={form.contact_email||'cliente@email.com'}/></label>}</div>{err&&<div className="loginError">{err}</div>}<div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}><Plus size={16}/>{saving?'Criando...':'Criar cliente'}</button></div></form></div>
}

const tabs=['Visão geral','Produção','Aprovações','Calendário','Entregas','Financeiro','Contrato e escopo','Arquivos'];
function Client360({client,ctx,tab,setTab,onBack,onClientUpdated}){const [editing,setEditing]=useState(false);return <section className="client360"><div className="clientTopActions"><button className="back" onClick={onBack}><ChevronLeft size={16}/> Clientes</button><button className="secondary" onClick={()=>setEditing(true)}><Pencil size={15}/> Editar cliente</button></div><div className="clientTitle"><div className="clientInitial bigInitial">{client.name[0]}</div><div><small>{client.status==='active'?'CLIENTE ATIVO':client.status==='paused'?'CLIENTE PAUSADO':'CLIENTE ARQUIVADO'}</small><h2>{client.name}</h2><p>Cliente 360° · {ctx.organization.name}</p></div></div><div className="tabs">{tabs.map(t=><button type="button" className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Visão geral'?<ClientHome setTab={setTab}/>:tab==='Contrato e escopo'?<ContractScope client={client} ctx={ctx}/>:<ClientSubpage tab={tab} client={client}/>} {editing&&<EditClientModal client={client} onClose={()=>setEditing(false)} onSaved={c=>{onClientUpdated(c);setEditing(false)}}/>}</section>}
function EditClientModal({client,onClose,onSaved}){const [form,setForm]=useState({name:client.name||'',legal_name:client.legal_name||'',status:client.status||'active',contact_name:client.contact_name||'',contact_email:client.contact_email||'',whatsapp:client.whatsapp||'',instagram:client.instagram||'',website:client.website||'',notes:client.notes||'',portal_email:client.portal_email||'',portal_access_status:client.portal_access_status||'not_requested'}),[saving,setSaving]=useState(false),[err,setErr]=useState('');function f(k,v){setForm(x=>({...x,[k]:v}))}async function save(e){e.preventDefault();setSaving(true);setErr('');const payload={...form,legal_name:form.legal_name||null,contact_name:form.contact_name||null,contact_email:form.contact_email||null,whatsapp:form.whatsapp||null,instagram:form.instagram||null,website:form.website||null,notes:form.notes||null,portal_email:form.portal_email||null};const {data,error}=await supabase.from('clients').update(payload).eq('id',client.id).select().single();if(error)setErr(error.message);else onSaved(data);setSaving(false)}return <div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modalCard" onSubmit={save}><div className="modalHead"><div><small>CLIENTE 360°</small><h2>Editar cliente</h2><p>Atualize os dados sem precisar abrir o Supabase.</p></div><button type="button" className="modalClose" onClick={onClose}><X size={20}/></button></div><div className="formGrid"><label>Nome do cliente *<input required autoFocus value={form.name} onChange={e=>f('name',e.target.value)}/></label><label>Empresa / razão social<input value={form.legal_name} onChange={e=>f('legal_name',e.target.value)}/></label><label>Status<select value={form.status} onChange={e=>f('status',e.target.value)}><option value="active">Ativo</option><option value="paused">Pausado</option><option value="archived">Arquivado</option></select></label><label>Contato principal<input value={form.contact_name} onChange={e=>f('contact_name',e.target.value)}/></label><label>E-mail<input type="email" value={form.contact_email} onChange={e=>f('contact_email',e.target.value)}/></label><label>WhatsApp<input value={form.whatsapp} onChange={e=>f('whatsapp',e.target.value)}/></label><label>Instagram<input value={form.instagram} onChange={e=>f('instagram',e.target.value)}/></label><label>Site<input value={form.website} onChange={e=>f('website',e.target.value)}/></label><label>E-mail do portal<input type="email" value={form.portal_email} onChange={e=>f('portal_email',e.target.value)}/></label><label>Acesso ao portal<select value={form.portal_access_status} onChange={e=>f('portal_access_status',e.target.value)}><option value="not_requested">Não solicitado</option><option value="pending">Pendente</option><option value="active">Ativo</option></select></label><label className="wide">Observações<textarea value={form.notes} onChange={e=>f('notes',e.target.value)}/></label></div>{err&&<div className="loginError">{err}</div>}<div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}><Save size={16}/>{saving?'Salvando...':'Salvar alterações'}</button></div></form></div>}

function ClientHome({setTab}){const cards=[['Produção','Demandas e andamento',Clapperboard],['Aprovações','Materiais aguardando cliente',CircleCheckBig],['Calendário','Planejamento editorial',CalendarDays],['Entregas','Histórico entregue',PackageCheck],['Financeiro','Mensalidades e adicionais',WalletCards],['Contrato e escopo','Pacote, limites e extras',FileText],['Arquivos','Materiais do cliente',FolderOpen]];return <><div className="notice"><Clock3 size={18}/><div><b>Escopo em definição</b><span>Você pode deixar quantidades e valores como “A definir” e completar depois da reunião.</span></div></div><div className="hubCards">{cards.map(([title,desc,I])=><button type="button" key={title} onClick={()=>setTab(title)}><I size={21}/><div><h3>{title}</h3><p>{desc}</p></div><ArrowUpRight size={17}/></button>)}</div></>}
function ClientSubpage({tab,client}){if(tab==='Produção')return <Production client={client}/>;if(tab==='Aprovações')return <ReviewList client={client} mode="agency"/>;if(tab==='Entregas')return <DemandList client={client} statuses={['delivered']} title="Entregas"/>;if(tab==='Arquivos')return <DemandList client={client} title="Arquivos e versões" files/>;if(tab==='Financeiro')return <Finance ctx={null} client={client}/>;return <div className="emptyModule compact"><small>{client.name.toUpperCase()}</small><h2>{tab}</h2><p>Área vinculada a este cliente. A próxima camada deste módulo será conectada aos dados operacionais.</p></div>}
function Production({client}){const [items,setItems]=useState([]),[show,setShow]=useState(false),[selected,setSelected]=useState(null);async function load(){const {data}=await supabase.from('demands').select('*').eq('client_id',client.id).order('created_at',{ascending:false});setItems(data||[])}useEffect(()=>{load()},[client.id]);if(selected)return <DemandDetail demand={selected} onBack={()=>{setSelected(null);load()}}/>;return <div className="production"><div className="sectionHead"><div><small>PRODUÇÃO REAL</small><h3>Demandas</h3><p>Crie a demanda, envie versões e acompanhe o fluxo.</p></div><button className="primary" onClick={()=>setShow(true)}><Plus size={16}/> Nova demanda</button></div>{items.length?<div className="demandGrid">{items.map(d=><button className="demandCard" key={d.id} onClick={()=>setSelected(d)}><div><span className={'demandStatus '+d.status}>{statusLabel(d.status)}</span><h3>{d.title}</h3><p>{d.type} · {d.due_date?`prazo ${dateBR(d.due_date)}`:'sem prazo'}</p></div><ArrowUpRight size={17}/></button>)}</div>:<div className="emptyModule compact"><small>SEM DEMANDAS</small><h2>Comece pela primeira produção.</h2><p>Cadastre um vídeo ou outra entrega deste cliente.</p></div>}{show&&<NewDemand client={client} onClose={()=>setShow(false)} onCreated={d=>{setShow(false);setSelected(d)}}/>}</div>}
function NewDemand({client,onClose,onCreated}){const [f,setF]=useState({title:'',type:'Vídeo / Reel',briefing:'',responsible_name:'',due_date:'',publish_date:'',notes:''}),[busy,setBusy]=useState(false),[err,setErr]=useState('');async function submit(e){e.preventDefault();setBusy(true);const {data,error}=await supabase.from('demands').insert({organization_id:client.organization_id,client_id:client.id,title:f.title,type:f.type,briefing:f.briefing||null,responsible_name:f.responsible_name||null,due_date:f.due_date||null,publish_date:f.publish_date||null,notes:f.notes||null,status:'briefing'}).select().single();if(error){setErr(error.message);setBusy(false)}else onCreated(data)}return <div className="modalBackdrop"><form className="modalCard" onSubmit={submit}><div className="modalHead"><div><small>NOVA DEMANDA</small><h2>O que vamos produzir?</h2></div><button type="button" className="modalClose" onClick={onClose}><X/></button></div><div className="formGrid"><label>Título *<input required value={f.title} onChange={e=>setF({...f,title:e.target.value})} placeholder="Ex.: Reel — Como escolher uma IPA"/></label><label>Tipo<select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option>Vídeo / Reel</option><option>Criativo estático</option><option>Carrossel</option><option>Outro</option></select></label><label>Responsável<input value={f.responsible_name} onChange={e=>setF({...f,responsible_name:e.target.value})}/></label><label>Prazo<input type="date" value={f.due_date} onChange={e=>setF({...f,due_date:e.target.value})}/></label><label>Publicação<input type="date" value={f.publish_date} onChange={e=>setF({...f,publish_date:e.target.value})}/></label><label className="wide">Briefing<textarea value={f.briefing} onChange={e=>setF({...f,briefing:e.target.value})}/></label><label className="wide">Observações<textarea value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></label></div>{err&&<div className="loginError">{err}</div>}<div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Criando...':'Criar demanda'}</button></div></form></div>}
function DemandDetail({demand,onBack}){const [pendingUpload,setPendingUpload]=useState(null);const uploadController=useRef(null);useEffect(()=>()=>uploadController.current?.abort(),[]);const [d,setD]=useState(demand),[versions,setVersions]=useState([]),[uploading,setUploading]=useState(false),[progress,setProgress]=useState(0),[msg,setMsg]=useState('');async function load(){const {data}=await supabase.from('demand_versions').select('*').eq('demand_id',d.id).order('version_number',{ascending:false});setVersions(data||[])}useEffect(()=>{load()},[d.id]);async function upload(e){
 const input=e.target,file=input.files?.[0];if(!file)return;
 const controller=new AbortController();uploadController.current=controller;
 setUploading(true);setProgress(0);setMsg('');
 try {
  const result=await uploadProduction(supabase,d.id,file,setProgress,controller.signal,setPendingUpload);
  setD({...d,status:'internal_review'});await load();setMsg(`V${result.versionNumber} enviada com sucesso.`);
 } catch(error){setMsg(error.message)}
 finally{setUploading(false);uploadController.current=null;input.value=''}
}async function send(v){await supabase.from('demand_versions').update({status:'sent_for_review'}).eq('id',v.id);await supabase.from('demands').update({status:'with_client'}).eq('id',d.id);await supabase.from('approval_events').insert({demand_version_id:v.id,user_id:(await supabase.auth.getUser()).data.user.id,event:'sent'});setD({...d,status:'with_client'});load()}async function deliver(v){await supabase.from('demand_versions').update({status:'delivered'}).eq('id',v.id);await supabase.from('demands').update({status:'delivered'}).eq('id',d.id);await supabase.from('approval_events').insert({demand_version_id:v.id,user_id:(await supabase.auth.getUser()).data.user.id,event:'delivered'});setD({...d,status:'delivered'});load()}return <div><button className="back" onClick={onBack}><ChevronLeft size={16}/> Produção</button><div className="sectionHead"><div><span className={'demandStatus '+d.status}>{statusLabel(d.status)}</span><h2>{d.title}</h2><p>{d.briefing||'Sem briefing cadastrado.'}</p></div><label className="primary uploadBtn"><Upload size={16}/>{uploading?`Enviando ${progress}%`:'Enviar nova versão'}<input type="file" accept="video/mp4,video/quicktime,video/webm,image/jpeg,image/png,application/pdf" onChange={upload} disabled={uploading}/></label>{uploading&&<button className="secondary" onClick={()=>uploadController.current?.abort()}>Pausar envio</button>}{!uploading&&pendingUpload&&<button className="secondary" onClick={async()=>{try{await discardProduction(supabase,pendingUpload);setPendingUpload(null);setMsg("Envio pendente descartado.")}catch(e){setMsg(e.message)}}}>Descartar envio pendente</button>}</div><div className="versionList">{versions.map(v=><VersionCard key={v.id} v={v} agency onSend={()=>send(v)} onDeliver={()=>deliver(v)}/>)}</div>{!versions.length&&<div className="emptyModule compact"><small>VERSÕES</small><h2>Nenhum arquivo enviado.</h2><p>Envie a V1 para iniciar o histórico desta demanda.</p></div>}{msg&&<div className="loginError">{msg}</div>}</div>}
function VersionCard({v,agency,onSend,onDeliver,onDecision}){const [url,setUrl]=useState(''),[fileError,setFileError]=useState('');useEffect(()=>{
 let active=true;const refresh=()=>fileApi(supabase,{action:'read',versionId:v.id}).then(data=>{if(active){setUrl(data.url);setFileError('')}}).catch(e=>{if(active){setUrl('');setFileError(e.message)}});
 setUrl('');refresh();const timer=setInterval(refresh,50*60*1000);return()=>{active=false;clearInterval(timer)};
},[v.id,v.storage_path,v.status]);return <article className="versionCard"><div className="versionPreview">{url&&v.mime_type?.startsWith('video/')?<video controls preload="metadata" src={url}/>:url&&v.mime_type?.startsWith('image/')?<img src={url} alt="Prévia"/>:<FileText size={36}/>}</div><div className="versionInfo"><small>VERSÃO {v.version_number}</small><h3>{v.file_name}</h3><p>{v.status.replaceAll('_',' ')} · {formatBytes(v.file_size)}</p>{fileError&&<div className="loginError">{fileError}</div>}<div className="versionActions">{url&&<a className="secondary" href={url} target="_blank" rel="noopener noreferrer">Abrir arquivo</a>}{agency&&v.status==='draft'&&<button className="primary" onClick={onSend}><Send size={15}/> Enviar para aprovação</button>}{agency&&v.status==='approved'&&<button className="primary" onClick={onDeliver}><PackageCheck size={15}/> Marcar entregue</button>}{onDecision&&v.status==='sent_for_review'&&<><button className="primary" onClick={()=>onDecision(v,'approved')}><Check size={15}/> Aprovar</button><button className="secondary" onClick={()=>onDecision(v,'changes_requested')}><RefreshCw size={15}/> Pedir alteração</button></>}</div></div></article>}
function ReviewList({client,mode}){const [rows,setRows]=useState([]);async function load(){const {data}=await supabase.from('demands').select('*, demand_versions(*)').eq('client_id',client.id).eq('status','with_client').order('created_at',{ascending:false});setRows(data||[])}useEffect(()=>{load()},[client.id]);return <div><div className="sectionHead"><div><small>APROVAÇÕES</small><h3>Aguardando cliente</h3></div></div>{rows.map(d=>{const v=[...(d.demand_versions||[])].sort((a,b)=>b.version_number-a.version_number)[0];return v?<div key={d.id}><h3>{d.title}</h3><VersionCard v={v}/></div>:null})}{!rows.length&&<div className="emptyModule compact"><h2>Nada aguardando aprovação.</h2><p>Quando uma versão for enviada ao cliente, ela aparece aqui.</p></div>}</div>}
function DemandList({client,statuses,title,files}){const [rows,setRows]=useState([]);useEffect(()=>{let q=supabase.from('demands').select('*').eq('client_id',client.id);if(statuses)q=q.in('status',statuses);q.order('created_at',{ascending:false}).then(({data})=>setRows(data||[]))},[client.id]);return <div><div className="sectionHead"><div><small>{files?'ARQUIVOS':'HISTÓRICO'}</small><h3>{title}</h3></div></div><div className="demandGrid">{rows.map(d=><article className="demandCard" key={d.id}><div><span className={'demandStatus '+d.status}>{statusLabel(d.status)}</span><h3>{d.title}</h3><p>{d.type}</p></div></article>)}</div>{!rows.length&&<div className="emptyModule compact"><h2>Nenhum item ainda.</h2></div>}</div>}
function statusLabel(s){return ({briefing:'Briefing',awaiting_material:'Aguardando material',in_production:'Em produção',internal_review:'Revisão interna',with_client:'Com cliente',adjustments:'Ajustes',approved:'Aprovado',delivered:'Entregue'})[s]||s}function dateBR(v){return new Date(v+'T12:00:00').toLocaleDateString('pt-BR')}function formatBytes(n){if(!n)return '';if(n<1048576)return Math.round(n/1024)+' KB';return (n/1048576).toFixed(1)+' MB'}
function ContractScope({client,ctx}){const [contract,setContract]=useState(null),[items,setItems]=useState([]),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[msg,setMsg]=useState('');
 useEffect(()=>{load()},[client.id]);async function load(){setLoading(true);const {data,error}=await supabase.from('contracts').select('*').eq('client_id',client.id).order('created_at',{ascending:false}).limit(1).maybeSingle();if(error){setMsg(error.message);setLoading(false);return}let ct=data;if(!ct){const ins=await supabase.from('contracts').insert({client_id:client.id,organization_id:ctx.organization.id,status:'defining'}).select().single();ct=ins.data;if(ins.error)setMsg(ins.error.message)}setContract(ct);if(ct){const {data:its}=await supabase.from('contract_items').select('*').eq('contract_id',ct.id).order('sort_order');setItems(its||[])}setLoading(false)}
 function c(k,v){setContract(x=>({...x,[k]:v}))}function i(id,k,v){setItems(x=>x.map(a=>a.id===id?{...a,[k]:v}:a))}
 async function save(){setSaving(true);setMsg('');const payload={status:contract.status,monthly_value:blankNum(contract.monthly_value),start_date:contract.start_date||null,end_date:contract.end_date||null,due_day:blankNum(contract.due_day),notes:contract.notes||null};const {error}=await supabase.from('contracts').update(payload).eq('id',contract.id);if(error){setMsg(error.message);setSaving(false);return}for(const item of items){const {error:e}=await supabase.from('contract_items').update({name:item.name,monthly_quantity:blankNum(item.monthly_quantity),extra_value:blankNum(item.extra_value),is_active:item.is_active,sort_order:item.sort_order}).eq('id',item.id);if(e){setMsg(e.message);setSaving(false);return}}setMsg('Alterações salvas.');setSaving(false)}
 async function add(){const {data,error}=await supabase.from('contract_items').insert({contract_id:contract.id,name:'Novo serviço',monthly_quantity:null,extra_value:null,is_active:true,sort_order:items.length}).select().single();if(error)setMsg(error.message);else setItems(x=>[...x,data])}
 async function remove(id){await supabase.from('contract_items').delete().eq('id',id);setItems(x=>x.filter(a=>a.id!==id))}
 if(loading)return <p>Carregando contrato...</p>;if(!contract)return <div className="loginError">{msg||'Não foi possível abrir o contrato.'}</div>;
 return <div className="contractWrap"><div className="sectionHead"><div><small>CONFIGURAÇÃO OPERACIONAL</small><h3>Contrato</h3><p>Campos vazios permanecem como “A definir”.</p></div><button className="primary" onClick={save} disabled={saving}><Save size={16}/>{saving?'Salvando...':'Salvar alterações'}</button></div><div className="formGrid"><label>Status<select value={contract.status} onChange={e=>c('status',e.target.value)}><option value="defining">Em definição</option><option value="active">Ativo</option><option value="paused">Pausado</option><option value="ended">Encerrado</option></select></label><label>Valor mensal (R$)<input type="number" placeholder="A definir" value={contract.monthly_value??''} onChange={e=>c('monthly_value',e.target.value)}/></label><label>Início<input type="date" value={contract.start_date||''} onChange={e=>c('start_date',e.target.value)}/></label><label>Término<input type="date" value={contract.end_date||''} onChange={e=>c('end_date',e.target.value)}/></label><label>Dia do vencimento<input type="number" min="1" max="31" placeholder="A definir" value={contract.due_day??''} onChange={e=>c('due_day',e.target.value)}/></label><label className="wide">Observações<textarea placeholder="Condições, detalhes comerciais, acordos..." value={contract.notes||''} onChange={e=>c('notes',e.target.value)}/></label></div><div className="scopeHead"><div><small>ESCOPO MENSAL</small><h3>Entregas contratadas</h3></div><button className="secondary" onClick={add}><Plus size={15}/> Adicionar serviço</button></div><div className="scopeTable"><div className="scopeRow scopeLabels"><span>ATIVO</span><span>ENTREGA</span><span>QTD. MENSAL</span><span>VALOR EXTRA</span><span/></div>{items.map(item=><div className="scopeRow" key={item.id}><label className="switch"><input type="checkbox" checked={item.is_active} onChange={e=>i(item.id,'is_active',e.target.checked)}/><i/></label><input value={item.name} onChange={e=>i(item.id,'name',e.target.value)}/><input type="number" min="0" placeholder="A definir" value={item.monthly_quantity??''} onChange={e=>i(item.id,'monthly_quantity',e.target.value)}/><input type="number" min="0" step="0.01" placeholder="A definir" value={item.extra_value??''} onChange={e=>i(item.id,'extra_value',e.target.value)}/><button className="iconDanger" onClick={()=>remove(item.id)} title="Remover"><Trash2 size={16}/></button></div>)}</div>{msg&&<div className={msg==='Alterações salvas.'?'saveMsg':'loginError'}>{msg}</div>}<div className="ruleNote"><b>Regra AVESSO:</b> quantidade vazia = <b>A definir</b>. Somente uma entrega marcada como <b>Entregue</b> consumirá o pacote mensal.</div></div>}
function blankNum(v){return v===''||v===null||v===undefined?null:Number(v)}


function Finance({ctx,client=null}){
 const [rows,setRows]=useState([]),[clients,setClients]=useState([]),[show,setShow]=useState(false),[edit,setEdit]=useState(null),[loading,setLoading]=useState(true);
 const orgId=ctx?.organization?.id;
 async function load(){setLoading(true);let q=supabase.from('financial_entries').select('*,clients(name)').order('due_date',{ascending:true});if(client)q=q.eq('client_id',client.id);else if(orgId)q=q.eq('organization_id',orgId);const {data}=await q;setRows(data||[]);if(!client&&orgId){const {data:c}=await supabase.from('clients').select('id,name').eq('organization_id',orgId).eq('status','active').order('name');setClients(c||[])}setLoading(false)}
 useEffect(()=>{load()},[client?.id,orgId]);
 const today=new Date().toISOString().slice(0,10), active=rows.filter(r=>r.status!=='cancelled'), receivable=active.filter(r=>r.status!=='paid'&&r.kind!=='expense').reduce((a,r)=>a+Number(r.amount||0)-Number(r.paid_amount||0),0), received=active.filter(r=>r.kind!=='expense').reduce((a,r)=>a+Number(r.paid_amount||0),0), overdue=active.filter(r=>r.kind!=='expense'&&r.status!=='paid'&&r.due_date&&r.due_date<today).reduce((a,r)=>a+Number(r.amount||0)-Number(r.paid_amount||0),0), expenses=active.filter(r=>r.kind==='expense').reduce((a,r)=>a+Number(r.amount||0),0);
 return <div className="financeWrap"><div className="sectionHead financeHeader"><div><small>FINANCEIRO OPERACIONAL</small><h3>{client?`Financeiro · ${client.name}`:'Financeiro da agência'}</h3><p>Mensalidades, extras, cobranças, pagamentos e custos em um só lugar.</p></div><button type="button" className="primary financeNewBtn" onClick={()=>{setEdit(null);setShow(true)}}><Plus size={18}/> {client?'Nova cobrança':'+ Novo lançamento'}</button></div><div className="financeQuickAction"><div><b>{client?'Registrar cobrança para este cliente':'Adicionar movimentação financeira'}</b><span>{client?'Mensalidade, extra ou cobrança avulsa.':'Mensalidade, extra, cobrança avulsa ou custo da agência.'}</span></div><button type="button" className="primary" onClick={()=>{setEdit(null);setShow(true)}}><Plus size={18}/>{client?'Nova cobrança':'Novo lançamento'}</button></div><div className="metrics financeMetrics"><article className="metric"><small>A RECEBER</small><strong>{money(receivable)}</strong><span>saldo pendente</span></article><article className="metric"><small>RECEBIDO</small><strong>{money(received)}</strong><span>pagamentos registrados</span></article><article className="metric"><small>VENCIDO</small><strong>{money(overdue)}</strong><span>pendências vencidas</span></article>{!client&&<article className="metric"><small>CUSTOS</small><strong>{money(expenses)}</strong><span>operação registrada</span></article>}</div><div className="financeTable"><div className="financeRow labels"><span>DESCRIÇÃO</span><span>CLIENTE</span><span>VENCIMENTO</span><span>VALOR</span><span>STATUS</span><span></span></div>{rows.map(r=>{const late=r.kind!=='expense'&&r.status!=='paid'&&r.due_date&&r.due_date<today;return <button className="financeRow" key={r.id} onClick={()=>{setEdit(r);setShow(true)}}><span><b>{r.description}</b><small>{kindLabel(r.kind)}</small></span><span>{r.clients?.name||'—'}</span><span>{r.due_date?dateBR(r.due_date):'—'}</span><span>{money(r.amount)}</span><span><i className={'finStatus '+(late?'late':r.status)}>{late?'Vencido':finStatus(r.status)}</i></span><span><Pencil size={15}/></span></button>})}</div>{!loading&&!rows.length&&<div className="emptyModule compact"><h2>Nenhum lançamento ainda.</h2><p>Cadastre a primeira mensalidade, extra, cobrança avulsa ou custo.</p></div>}{show&&<FinanceModal ctx={ctx} client={client} clients={clients} entry={edit} onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}</div>
}
function FinanceModal({ctx,client,clients,entry,onClose,onSaved}){const [f,setF]=useState({client_id:entry?.client_id||client?.id||'',kind:entry?.kind||(client?'monthly':'one_off'),description:entry?.description||'',amount:entry?.amount??'',due_date:entry?.due_date||'',competence:entry?.competence||'',status:entry?.status||'to_charge',paid_amount:entry?.paid_amount??0,notes:entry?.notes||''}),[busy,setBusy]=useState(false),[err,setErr]=useState('');function u(k,v){setF(x=>({...x,[k]:v}))}async function save(e){e.preventDefault();setBusy(true);setErr('');let organization_id=ctx?.organization?.id;if(!organization_id&&client){const {data}=await supabase.from('clients').select('organization_id').eq('id',client.id).single();organization_id=data?.organization_id}const payload={organization_id,client_id:f.kind==='expense'?null:(f.client_id||null),kind:f.kind,description:f.description,amount:Number(f.amount),due_date:f.due_date||null,competence:f.competence||null,status:f.status,paid_amount:Number(f.paid_amount||0),paid_at:f.status==='paid'?new Date().toISOString():null,notes:f.notes||null};const res=entry?await supabase.from('financial_entries').update(payload).eq('id',entry.id):await supabase.from('financial_entries').insert(payload);if(res.error){setErr(res.error.message);setBusy(false);return}onSaved()}async function remove(){if(!entry)return;await supabase.from('financial_entries').delete().eq('id',entry.id);onSaved()}return <div className="modalShade"><form className="modalCard" onSubmit={save}><div className="modalTop"><div><small>FINANCEIRO</small><h3>{entry?'Editar lançamento':'Novo lançamento'}</h3></div><button type="button" onClick={onClose}><X/></button></div><div className="formGrid"><label>Tipo<select value={f.kind} onChange={e=>u('kind',e.target.value)}><option value="monthly">Mensalidade</option><option value="extra">Extra</option><option value="one_off">Cobrança avulsa</option>{!client&&<option value="expense">Custo da agência</option>}</select></label>{f.kind!=='expense'&&<label>Cliente<select value={f.client_id} onChange={e=>u('client_id',e.target.value)} required><option value="">Selecione</option>{(client?[client]:clients).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}<label className="wide">Descrição<input value={f.description} onChange={e=>u('description',e.target.value)} required placeholder="Ex.: Mensalidade outubro"/></label><label>Valor (R$)<input type="number" min="0" step="0.01" value={f.amount} onChange={e=>u('amount',e.target.value)} required/></label><label>Vencimento<input type="date" value={f.due_date} onChange={e=>u('due_date',e.target.value)}/></label><label>Competência<input type="date" value={f.competence} onChange={e=>u('competence',e.target.value)}/></label><label>Status<select value={f.status} onChange={e=>u('status',e.target.value)}><option value="to_charge">A cobrar</option><option value="charged">Cobrado</option><option value="paid">Pago</option><option value="cancelled">Cancelado</option></select></label><label>Valor já pago<input type="number" min="0" step="0.01" value={f.paid_amount} onChange={e=>u('paid_amount',e.target.value)}/></label><label className="wide">Observações<textarea value={f.notes} onChange={e=>u('notes',e.target.value)} placeholder="Detalhes da cobrança ou pagamento..."/></label></div>{err&&<div className="loginError">{err}</div>}<div className="modalActions">{entry&&<button type="button" className="dangerText" onClick={remove}><Trash2 size={15}/> Excluir</button>}<span/><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}><Save size={15}/>{busy?'Salvando...':'Salvar'}</button></div></form></div>}
function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}function kindLabel(k){return ({monthly:'Mensalidade',extra:'Extra',one_off:'Avulso',expense:'Custo'})[k]||k}function finStatus(s){return ({to_charge:'A cobrar',charged:'Cobrado',paid:'Pago',cancelled:'Cancelado'})[s]||s}

function ClientPortal({ctx}){const [active,setActive]=useState('Início'),[mobile,setMobile]=useState(false);return <main className="shell clientShell"><Sidebar nav={clientNav} active={active} setActive={setActive} mobile={mobile} setMobile={setMobile} org={ctx.client?.name||'Meu espaço'} client/><section className="content"><Top ctx={ctx} mobile={mobile} setMobile={setMobile} eyebrow="PORTAL DO CLIENTE" subtitle={`Seu espaço na ${ctx.organization?.name||'agência'}.`}/><div className="clientWelcome"><div><small>SEU ESPAÇO</small><h2>{ctx.client?.name}</h2><p>Produção, aprovações, calendário e entregas.</p></div><div className="clientBadge">CLIENTE</div></div>{active==='Aprovações'?<ClientApprovals client={ctx.client}/>:active==='Entregas'?<DemandList client={ctx.client} statuses={['delivered']} title="Entregas"/>:active==='Arquivos'?<DemandList client={ctx.client} title="Arquivos" files/>:<EmptyModule name={active}/>}<div className="privacyNote">Você está vendo apenas informações vinculadas a <b>{ctx.client?.name}</b>.</div></section></main>}
function ClientApprovals({client}){const [rows,setRows]=useState([]);async function load(){const {data}=await supabase.from('demands').select('*, demand_versions(*)').eq('client_id',client.id).eq('status','with_client').order('created_at',{ascending:false});setRows(data||[])}useEffect(()=>{load()},[client.id]);async function decide(d,v,status){const user=(await supabase.auth.getUser()).data.user;await supabase.from('demand_versions').update({status}).eq('id',v.id);await supabase.from('demands').update({status:status==='approved'?'approved':'adjustments'}).eq('id',d.id);await supabase.from('approval_events').insert({demand_version_id:v.id,user_id:user.id,event:status==='approved'?'approved':'changes_requested'});load()}return <div><div className="sectionHead"><div><small>SUA APROVAÇÃO</small><h3>Materiais para revisar</h3><p>Assista à versão e aprove ou solicite alterações.</p></div></div>{rows.map(d=>{const v=[...(d.demand_versions||[])].sort((a,b)=>b.version_number-a.version_number)[0];return v?<div key={d.id} className="reviewBlock"><h3>{d.title}</h3><VersionCard v={v} onDecision={(vv,s)=>decide(d,vv,s)}/></div>:null})}{!rows.length&&<div className="emptyModule compact"><h2>Nada para aprovar agora.</h2><p>Quando a agência enviar uma versão, ela aparecerá aqui.</p></div>}</div>}
function Sidebar({nav,active,setActive,mobile,setMobile,org,client}){return <aside className={mobile?'side open':'side'}><div className="brand">AVESSO<span>.</span></div><div className="tag">{client?'SEU ESPAÇO\nCRIATIVO.':'A OPERAÇÃO\nPOR TRÁS\nDA CRIAÇÃO.'}</div><nav>{nav.map(([n,I])=><button key={n} className={active===n?'active':''} onClick={()=>{setActive(n);setMobile(false)}}><I size={19}/><span>{n}</span></button>)}</nav><div className="org"><span className="dot"/><div><small>{client?'CLIENTE':'ORGANIZAÇÃO'}</small><strong>{org}</strong></div></div>{!client&&<button className="settings"><Settings size={18}/>Configurações</button>}<button className="logout" onClick={()=>supabase.auth.signOut()}><LogOut size={17}/>Sair</button><div className="version">V 0.11.0 · FINANCEIRO REAL</div></aside>}
function Top({ctx,mobile,setMobile,eyebrow,subtitle}){return <header><button className="hamb" onClick={()=>setMobile(!mobile)}>{mobile?<X/>:<Menu/>}</button><div><div className="eyebrow">{eyebrow}</div><h1>Olá, <strong>{ctx.name}.</strong></h1><p>{subtitle}</p></div><div className="tools"><div className="search"><Search size={17}/><span>Buscar no AVESSO...</span></div><button className="bell"><Bell size={18}/></button><div className="avatar">{ctx.name?.[0]?.toUpperCase()}</div></div></header>}
function Splash({text='Carregando AVESSO...'}){return <main className="splash"><div className="brand big">AVESSO<span>.</span></div><p>{text}</p></main>}
